import{_ as e,o as s,c as a,a2 as i}from"./chunks/framework.CHX4lV2z.js";const g=JSON.parse('{"title":"Reports and Visuals","description":"","frontmatter":{},"headers":[],"relativePath":"plugin-catalog/tokenpilot/reports-and-visuals.md","filePath":"plugin-catalog/tokenpilot/reports-and-visuals.md","lastUpdated":1789811186000}'),l={name:"plugin-catalog/tokenpilot/reports-and-visuals.md"};function n(r,t,o,d,h,p){return s(),a("div",null,[...t[0]||(t[0]=[i(`<h1 id="reports-and-visuals" tabindex="-1">Reports and Visuals <a class="header-anchor" href="#reports-and-visuals" aria-label="Permalink to &quot;Reports and Visuals&quot;">​</a></h1><p>TokenPilot provides built-in reporting and a visual inspector so you can see exactly what it&#39;s doing.</p><h2 id="host-entry-points" tabindex="-1">Host Entry Points <a class="header-anchor" href="#host-entry-points" aria-label="Permalink to &quot;Host Entry Points&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Host</th><th style="text-align:left;">Report or status</th><th style="text-align:left;">Visual Inspector</th></tr></thead><tbody><tr><td style="text-align:left;">OpenClaw</td><td style="text-align:left;"><code>lightrsi openclaw report</code></td><td style="text-align:left;"><code>lightrsi openclaw visual</code></td></tr><tr><td style="text-align:left;">Codex</td><td style="text-align:left;"><code>lightrsi codex report</code></td><td style="text-align:left;"><code>lightrsi codex visual</code></td></tr><tr><td style="text-align:left;">Claude Code</td><td style="text-align:left;"><code>lightrsi claude-code report</code></td><td style="text-align:left;"><code>lightrsi claude-code visual</code></td></tr><tr><td style="text-align:left;">DeepSeek Harness</td><td style="text-align:left;"><code>/tokenpilot-status</code> inside a Harness session</td><td style="text-align:left;">Shared Visual interface does not apply</td></tr></tbody></table><p>DeepSeek Harness reports estimator activity, scheduling, application, and deferrals through its native read-only status command. See <a href="/LightRSI/hosts/deepseek-harness#verify-in-a-session">status fields</a>. The shared report metrics and Visual walkthrough below apply to OpenClaw, Codex, and Claude Code.</p><h2 id="the-report-command" tabindex="-1">The Report Command <a class="header-anchor" href="#the-report-command" aria-label="Permalink to &quot;The Report Command&quot;">​</a></h2><p>The <code>report</code> command shows a summary of token usage, cache efficiency, and cost savings for the current session:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Standalone CLI</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lightrsi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> report</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Per-host</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lightrsi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openclaw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> report</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lightrsi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> report</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lightrsi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> claude-code</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> report</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Inside OpenClaw</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/lightrsi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> report</span></span></code></pre></div><h3 id="what-each-metric-means" tabindex="-1">What Each Metric Means <a class="header-anchor" href="#what-each-metric-means" aria-label="Permalink to &quot;What Each Metric Means&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Metric</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Input tokens</strong></td><td style="text-align:left;">Total tokens sent to the model (lower is better)</td></tr><tr><td style="text-align:left;"><strong>Cache read</strong></td><td style="text-align:left;">Tokens served from the model API cache (higher is better)</td></tr><tr><td style="text-align:left;"><strong>Cache miss</strong></td><td style="text-align:left;">Tokens that had to be recomputed (lower is better)</td></tr><tr><td style="text-align:left;"><strong>Output tokens</strong></td><td style="text-align:left;">Tokens generated by the model</td></tr><tr><td style="text-align:left;"><strong>Cost</strong></td><td style="text-align:left;">Estimated API cost in USD</td></tr><tr><td style="text-align:left;"><strong>Cache hit rate</strong></td><td style="text-align:left;">Percentage of input tokens served from cache</td></tr></tbody></table><h2 id="visual-inspector" tabindex="-1">Visual Inspector <a class="header-anchor" href="#visual-inspector" aria-label="Permalink to &quot;Visual Inspector&quot;">​</a></h2><p>The visual inspector is a browser-based dashboard showing real-time TokenPilot behavior:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lightrsi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> visual</span></span></code></pre></div><p>This opens your default browser with three views: stabilizer, reduction, and eviction.</p><h2 id="context-cleaner-results" tabindex="-1">Context Cleaner Results <a class="header-anchor" href="#context-cleaner-results" aria-label="Permalink to &quot;Context Cleaner Results&quot;">​</a></h2><p>User-approved Cleaner results are tracked by plan receipt, separately from the general session report:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lightrsi</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">hos</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --status</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">plan-i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>Use <code>openclaw</code>, <code>codex</code>, or <code>claude-code</code> for <code>&lt;host&gt;</code>. Distinguish estimated and scheduled savings from applied savings; character-based counts are not token counts or provider billing savings. See <a href="/LightRSI/user-guide/context-cleaner#_3-check-the-result">Context Cleaner</a>. DeepSeek Harness does not currently expose this Cleaner command.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/LightRSI/plugin-catalog/tokenpilot/benchmarks">Benchmarks</a> — evaluation results</li><li><a href="/LightRSI/plugin-catalog/tokenpilot/troubleshooting">Troubleshooting</a> — common problems</li><li><a href="/LightRSI/user-guide/cli-reference">CLI Reference</a> — all commands</li></ul>`,20)])])}const k=e(l,[["render",n]]);export{g as __pageData,k as default};
